import{_ as r,l as n,o as a,c as i,v as t,p as d,x as o,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"蹦床与尾递归","description":"","frontmatter":{"title":"蹦床与尾递归","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/trampolining.md","filePath":"cs/trampolining.md","lastUpdated":1789023840000}'),h={name:"cs/trampolining.md"};function u(_,e,m,T,k,A){const l=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="蹦床与尾递归" tabindex="-1">蹦床与尾递归 <a class="header-anchor" href="#蹦床与尾递归" aria-label="Permalink to &quot;蹦床与尾递归&quot;">​</a></h1><div class="epigraph"><p>宿主语言不保证尾调用时，把「下一步计算」做成 thunk 返回给循环：蹦床反复调用，栈深度保持常数。</p><footer>—— 据 Steele 尾调用讨论；Baker, Cheney on the M.T.A.；对照[尾调用优化](/cs/tail-call-opt) 与 CPS 整理</footer></div><p>上一课<a href="/cs/coroutines-impl">协程</a> 用帧暂停。缺口是在<strong>无 TCO 的宿主</strong>（Java、C# 历史、JS 引擎不完全保证）实现 Scheme 式互递归：蹦床。虚表下一课。不重写 CPS 变换全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CPS 后全是尾调用，若 <code>call</code> 真的建帧则爆栈。蹦床：函数返回 <code>Bounce { thunk }</code> 或 <code>Done { value }</code>，驱动循环 <code>while (bounce) thunk()</code>。缺口是<strong>驱动器</strong>，不是 yield 状态机。</p><p>Cheney on the MTA：用垃圾回收当栈——极端蹦床，点名。</p><h3 id="蹦床不是协程的-yield" tabindex="-1">蹦床不是协程的 yield <a class="header-anchor" href="#蹦床不是协程的-yield" aria-label="Permalink to &quot;蹦床不是协程的 yield&quot;">​</a></h3><p>yield 把控制交回调用者并保存局部；蹦床通常不把中间结果交给用户，只给驱动器。用户看来仍是一次 <code>eval</code>。</p><p><span class="marginnote">Baker 的 MTA。Steele。SML 编译到 C 的历史技巧。本课工程补丁，优先仍是真 TCO。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约定：尾位置不调用而返回闭包。驱动：循环直到 <code>Done</code>。与闭包转换：thunk 即闭包。性能：间接多，可批处理若干步。</p>',11)),(a(),d(p,null,{default:o(()=>[c(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%B0%BE%E8%B0%83%E7%94%A8%22%5D%20--%3E%20TH%5B%22%E8%BF%94%E5%9B%9E%20thunk%22%5D%0A%20%20TH%20--%3E%20LOOP%5B%22%E8%B9%A6%E5%BA%8A%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20LOOP%20--%3E%20D%5B%22Done%20%E5%80%BC%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与 JIT：宿主若能识别驱动循环，仍难内联互递归。真 TCO 更好。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>调试栈无意义。异常：要穿过驱动器。不要在 thunk 里无意非尾调用。</p><p>与生成器：可把蹦床当无用户可见暂停的协程驱动。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写虚表。后课默认：无 TCO 时用蹦床保栈。下一课虚表与动态分派。</p><p>也不把蹦床当体操。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>蹦床：返回 thunk + 循环，模拟 TCO。</li><li>性能差于真尾调用；用于宿主限制。</li><li>thunk 是闭包。</li><li>出处：Steele；Baker MTA；对照 Appel CPS。</li></ul>',9))])}const C=r(h,[["render",u]]);export{B as __pageData,C as default};
